<?php
require_once __DIR__.'/../config/app.php';require_admin();
if(is_post()){verify_csrf();$paymentId=(int)($_POST['payment_id']??0);$action=$_POST['action']??'';$pdo=db();$pdo->beginTransaction();try{$s=$pdo->prepare('SELECT p.*,o.payment_status order_payment_status,o.order_status,o.fulfillment_method FROM payments p JOIN orders o ON o.id=p.order_id WHERE p.id=? FOR UPDATE');$s->execute([$paymentId]);$payment=$s->fetch();if(!$payment)throw new RuntimeException('Pembayaran tidak ditemukan.');if($action==='approve'){if($payment['method']==='transfer'&&$payment['status']!=='waiting_verification')throw new RuntimeException('Transfer belum menunggu verifikasi.');if($payment['method']==='cod'&&!in_array($payment['order_status'],$payment['fulfillment_method']==='pickup'?['packed','completed']:['shipped','completed'],true))throw new RuntimeException('COD belum dapat dikonfirmasi pada status pesanan ini.');$pdo->prepare("UPDATE payments SET status='paid',verified_by=?,verified_at=NOW() WHERE id=?")->execute([current_user()['id'],$paymentId]);$pdo->prepare("UPDATE orders SET payment_status='paid' WHERE id=?")->execute([$payment['order_id']]);flash('success','Pembayaran dikonfirmasi lunas.');}elseif($action==='reject'){if($payment['method']!=='transfer'||$payment['status']!=='waiting_verification')throw new RuntimeException('Pembayaran tidak dapat ditolak.');$pdo->prepare("UPDATE payments SET status='rejected',verified_by=?,verified_at=NOW() WHERE id=?")->execute([current_user()['id'],$paymentId]);$pdo->prepare("UPDATE orders SET payment_status='rejected' WHERE id=?")->execute([$payment['order_id']]);flash('warning','Bukti pembayaran ditolak. Pembeli dapat mengunggah ulang.');}elseif($action==='refund'){if($payment['status']!=='paid'||$payment['order_status']!=='cancelled')throw new RuntimeException('Refund hanya dapat dicatat untuk pesanan lunas yang dibatalkan.');$pdo->prepare("UPDATE payments SET status='refunded',verified_by=?,verified_at=NOW() WHERE id=?")->execute([current_user()['id'],$paymentId]);$pdo->prepare("UPDATE orders SET payment_status='refunded' WHERE id=?")->execute([$payment['order_id']]);flash('success','Pengembalian dana dicatat. Pastikan transfer refund benar-benar sudah dilakukan.');}else throw new RuntimeException('Aksi tidak valid.');$pdo->commit();notify_payment_status_changed((int)$payment['order_id']);}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('danger',$e->getMessage());}redirect('admin/payments.php');}
$status=$_GET['status']??'waiting_verification';$params=[];$where='1=1';if(in_array($status,['unpaid','waiting_verification','paid','rejected','refunded'],true)){$where='p.status=?';$params[]=$status;}$stmt=db()->prepare("SELECT p.*,o.order_number,o.order_status,o.fulfillment_method,o.payment_status,u.name customer_name,b.bank_name,b.account_number FROM payments p JOIN orders o ON o.id=p.order_id JOIN users u ON u.id=o.user_id LEFT JOIN bank_accounts b ON b.id=p.bank_account_id WHERE $where ORDER BY p.updated_at DESC");$stmt->execute($params);$payments=$stmt->fetchAll();$pageTitle='Pembayaran';require APP_ROOT.'/includes/admin-header.php';
?>
<div class="d-flex flex-wrap gap-2 mb-4"><?php foreach(['waiting_verification'=>'Menunggu Verifikasi','unpaid'=>'Belum Lunas','paid'=>'Lunas','rejected'=>'Ditolak','refunded'=>'Refund','all'=>'Semua'] as $key=>$label):?><a class="btn <?= $status===$key?'btn-primary':'btn-light' ?>" href="?status=<?= $key ?>"><?= $label ?></a><?php endforeach;?></div><div class="admin-card"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Pesanan</th><th>Pembeli</th><th>Metode</th><th>Jumlah</th><th>Status</th><th class="text-end">Aksi</th></tr></thead><tbody><?php if(!$payments):?><tr><td colspan="6" class="text-center text-muted py-5">Tidak ada pembayaran pada filter ini.</td></tr><?php endif;foreach($payments as $payment):?><tr><td><a class="fw-bold" href="<?= url('admin/order-detail.php?id='.$payment['order_id']) ?>"><?= e($payment['order_number']) ?></a><div class="small text-muted"><?= date('d/m/Y H:i',strtotime($payment['updated_at'])) ?></div></td><td><?= e($payment['customer_name']) ?></td><td><strong><?= $payment['fulfillment_method']==='pickup'?'COD DI TOKO':strtoupper($payment['method']) . ' ANTAR' ?></strong><?php if($payment['bank_name']):?><div class="small text-muted"><?= e($payment['bank_name']) ?></div><?php endif;?></td><td><?= rupiah($payment['amount']) ?></td><td><span class="badge text-bg-<?= status_class($payment['status']) ?>"><?= payment_status_label($payment['status']) ?></span></td><td class="text-end"><?php if($payment['proof_image']):?><a class="btn btn-sm btn-light" target="_blank" href="<?= url('proof.php?order_id='.$payment['order_id']) ?>"><i class="bi bi-image"></i></a><?php endif;?><?php if(($payment['method']==='transfer'&&$payment['status']==='waiting_verification')||($payment['method']==='cod'&&$payment['status']==='unpaid'&&in_array($payment['order_status'],$payment['fulfillment_method']==='pickup'?['packed','completed']:['shipped','completed'],true))):?><form method="post" class="d-inline"><?= csrf_field() ?><input type="hidden" name="payment_id" value="<?= $payment['id'] ?>"><input type="hidden" name="action" value="approve"><button class="btn btn-sm btn-success" data-confirm="Konfirmasi pembayaran ini sebagai lunas?"><i class="bi bi-check-lg"></i> Lunas</button></form><?php endif;?><?php if($payment['method']==='transfer'&&$payment['status']==='waiting_verification'):?><form method="post" class="d-inline"><?= csrf_field() ?><input type="hidden" name="payment_id" value="<?= $payment['id'] ?>"><input type="hidden" name="action" value="reject"><button class="btn btn-sm btn-outline-danger" data-confirm="Tolak bukti pembayaran ini?"><i class="bi bi-x-lg"></i></button></form><?php endif;?><?php if($payment['status']==='paid'&&$payment['order_status']==='cancelled'):?><form method="post" class="d-inline"><?= csrf_field() ?><input type="hidden" name="payment_id" value="<?= $payment['id'] ?>"><input type="hidden" name="action" value="refund"><button class="btn btn-sm btn-outline-warning" data-confirm="Tandai pengembalian dana sudah dilakukan?">Catat Refund</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></div>
<?php require APP_ROOT.'/includes/admin-footer.php';?>
